  if (/xlshiftup|xlup|up/.test(shiftText)) return "shift-up";
  if (/xlshifttoright|xltoright|right/.test(shiftText)) return "shift-right";
  if (/xlshiftdown|xldown|down/.test(shiftText)) return "shift-down";
