    const sumTarget = args[2] ? parseVbaRangeTarget(args[2], context) : criteriaTarget;
    const criteriaValues = vbaRangeValues(criteriaTarget);
    const sumValues = sumTarget ? vbaRangeValues(sumTarget) : criteriaValues;
