function pageSetupRangeFieldHtml(caption, field, value, mode = "range") {
  return `<label class="excel-dialog-field data-range-field page-setup-range-field"><span class="excel-dialog-caption">${accessKeyLabelHtml(caption)}</span><span class="data-range-input"><input type="text" data-page-setup-field="${escapeAttr(field)}" data-data-field="${escapeAttr(field)}" value="${escapeAttr(value || "")}" /><button class="data-range-picker" type="button" title="現在の選択範囲を使用" aria-label="${escapeAttr(caption)}に現在の選択範囲を使用" data-data-dialog-action="range-from-selection" data-data-range-target="${escapeAttr(field)}" data-data-range-mode="${escapeAttr(mode)}"></button></span></label>`;
}

function pageSetupPrintTitleRowsLabel(range) {
  const normalized = normalizePageSetupPrintTitleRows(range);
  return normalized?.label || "";
}

function pageSetupPrintTitleColumnsLabel(range) {
  const normalized = normalizePageSetupPrintTitleColumns(range);
  return normalized?.label || "";
}

function pageSetupFitToOptions(selected) {
  const value = normalizeFitToPageCount(selected);
  const numbers = [...new Set(["1", "2", value].filter((item) => item !== "auto"))]
    .sort((left, right) => Number(left) - Number(right));
  return [
    `<option value="auto"${value === "auto" ? " selected" : ""}>自動</option>`,
    ...numbers.map((item) => `<option value="${escapeAttr(item)}"${value === item ? " selected" : ""}>${escapeHtml(item)} ページ</option>`),
  ].join("");
}

function openPrintDialog() {
  if (!state.model) return;
  const sheet = activeSheet();
  const layout = ensurePageLayoutSettings(sheet);
  state.dataDialog = { type: "print" };
  closeDataDialog({ keepState: true });
  const paperOptions = PAGE_LAYOUT_PAPER_SIZES
    .map((paper) => `<option value="${escapeAttr(paper.value)}"${paper.value === layout.paperSize ? " selected" : ""}>${escapeHtml(paper.label)}</option>`)
    .join("");
  const overlay = document.createElement("div");
  overlay.className = "excel-dialog-overlay";
  overlay.id = "dataDialog";
  overlay.innerHTML = `
    <div class="excel-mini-dialog data-dialog print-dialog" role="dialog" aria-modal="true" aria-labelledby="printDialogTitle" data-data-dialog="print">
      <div class="excel-mini-titlebar" id="printDialogTitle">印刷</div>
      <div class="excel-mini-body data-dialog-body print-dialog-body">
        <div class="format-dialog-grid two">
          <label class="excel-dialog-field"><span class="excel-dialog-caption">${accessKeyLabelHtml("部数(C):")}</span><input type="number" min="1" max="999" value="1" data-data-field="printCopies" /></label>
          <label class="excel-dialog-field"><span class="excel-dialog-caption">${accessKeyLabelHtml("プリンター(P):")}</span><select data-data-field="printPrinter"><option>WebSheet PDF</option><option>既定のプリンター</option></select></label>
          <label class="excel-dialog-field"><span class="excel-dialog-caption">${accessKeyLabelHtml("設定(S):")}</span><select data-data-field="printScope"><option value="active">作業中のシートを印刷</option><option value="workbook">ブック全体を印刷</option><option value="selection">選択した部分を印刷</option></select></label>
          <label class="excel-dialog-field"><span class="excel-dialog-caption">${accessKeyLabelHtml("カラー モード(M):")}</span><select data-data-field="printColorMode"><option value="color"${layout.blackAndWhite ? "" : " selected"}>カラー</option><option value="blackWhite"${layout.blackAndWhite ? " selected" : ""}>白黒</option></select></label>
          <label class="excel-dialog-field"><span class="excel-dialog-caption">${accessKeyLabelHtml("印刷の向き(O):")}</span><select data-data-field="printOrientation"><option value="portrait"${layout.orientation === "portrait" ? " selected" : ""}>縦方向</option><option value="landscape"${layout.orientation === "landscape" ? " selected" : ""}>横方向</option></select></label>
          <label class="excel-dialog-field"><span class="excel-dialog-caption">${accessKeyLabelHtml("用紙サイズ(Z):")}</span><select data-data-field="printPaper">${paperOptions}</select></label>
          <label class="excel-dialog-field"><span class="excel-dialog-caption">${accessKeyLabelHtml("拡大/縮小(S):")}</span><input type="number" min="10" max="400" value="${layout.scale}" data-data-field="printScale" /></label>
        </div>
        <div class="print-dialog-preview" aria-label="印刷プレビュー">
          <div class="print-dialog-preview-toolbar">
            <button class="excel-mini-button print-preview-nav" type="button" data-data-dialog-action="print-preview-prev" aria-label="前のプレビュー">‹</button>
            <span class="print-dialog-preview-label" data-print-preview-label>プレビュー</span>
            <button class="excel-mini-button print-preview-nav" type="button" data-data-dialog-action="print-preview-next" aria-label="次のプレビュー">›</button>
          </div>
          <div class="print-dialog-preview-viewport" data-print-preview-viewport>
            <div class="print-dialog-preview-content" data-print-preview-content></div>
          </div>
          <div class="print-dialog-preview-summary" data-print-preview-summary></div>
        </div>
      </div>
      <div class="excel-mini-actions">
        <button class="excel-mini-button" type="button" data-data-dialog-action="print-page-setup">ページ設定(U)...</button>
        <button class="excel-mini-button is-primary" type="button" data-data-dialog-action="print-now">印刷(P)</button>
        <button class="excel-mini-button" type="button" data-data-dialog-action="cancel">キャンセル</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  overlay.querySelectorAll("[data-data-field^='print']").forEach((field) => {
    field.addEventListener("input", () => schedulePrintDialogPreviewSync(overlay, { resetIndex: field.dataset.dataField === "printScope" }));
    field.addEventListener("change", () => schedulePrintDialogPreviewSync(overlay, { resetIndex: field.dataset.dataField === "printScope" }));
  });
  syncPrintDialogPreview(overlay, { resetIndex: true });
  overlay.querySelector("[data-data-field='printCopies']")?.focus({ preventScroll: true });
  overlay.querySelector("[data-data-field='printCopies']")?.select?.();
  setStatus("印刷画面を開きました。");
}

function printDialogPageSettings(dialog) {
  const layout = ensurePageLayoutSettings(activeSheet());
  const paper = dialog?.querySelector("[data-data-field='printPaper']")?.value || layout.paperSize;
  const scale = Number(dialog?.querySelector("[data-data-field='printScale']")?.value);
  return {
    orientation: dialog?.querySelector("[data-data-field='printOrientation']")?.value === "landscape" ? "landscape" : "portrait",
    paperSize: PAGE_LAYOUT_PAPER_SIZES.some((item) => item.value === paper) ? paper : layout.paperSize,
    scale: Math.round(Math.max(10, Math.min(400, Number.isFinite(scale) ? scale : layout.scale))),
    blackAndWhite: dialog?.querySelector("[data-data-field='printColorMode']")?.value === "blackWhite",
  };
}

function printDialogSettingsKey(settings) {
  return JSON.stringify({
    orientation: settings.orientation,
    paperSize: settings.paperSize,
    scale: settings.scale,
    blackAndWhite: settings.blackAndWhite,
  });
}

function applyPrintDialogPageSettings(dialog, options = {}) {
  const sheet = activeSheet();
  if (!sheet || !dialog) return false;
  const current = ensurePageLayoutSettings(sheet);
  const next = printDialogPageSettings(dialog);
  if (printDialogSettingsKey(current) === printDialogSettingsKey(next)) return false;
  commitPageLayoutChange((layout) => {
    layout.orientation = next.orientation;
    layout.paperSize = next.paperSize;
    layout.scale = next.scale;
    layout.blackAndWhite = next.blackAndWhite;
  }, "印刷設定", options.statusMessage || "印刷設定を更新しました。", { render: options.render });
  return true;
}

function syncPrintDialogPreview(dialog) {
  renderPrintDialogPreview(dialog);
}

function schedulePrintDialogPreviewSync(dialog, options = {}) {
  if (!dialog) return;
  if (options.resetIndex) dialog.dataset.printPreviewIndex = "0";
  if (dialog.__printPreviewFrame) cancelAnimationFrame(dialog.__printPreviewFrame);
  dialog.__printPreviewFrame = requestAnimationFrame(() => {
    dialog.__printPreviewFrame = null;
    syncPrintDialogPreview(dialog);
  });
}

function renderPrintDialogPreview(dialog) {
  const content = dialog?.querySelector?.("[data-print-preview-content]");
  const label = dialog?.querySelector?.("[data-print-preview-label]");
  const summary = dialog?.querySelector?.("[data-print-preview-summary]");
  if (!content || !label || !summary) return;
  const pages = printPreviewPagesForDialog(dialog);
  if (!pages.length) {
    content.innerHTML = `<div class="print-dialog-preview-empty">印刷する範囲がありません。</div>`;
    label.textContent = "プレビュー";
    summary.textContent = "";
    syncPrintDialogPreviewNavigation(dialog, 0, 0);
    return;
  }
  const rawIndex = Math.round(Number(dialog.dataset.printPreviewIndex) || 0);
  const index = Math.max(0, Math.min(pages.length - 1, rawIndex));
  dialog.dataset.printPreviewIndex = String(index);
  const page = pages[index];
  const paper = printDialogPaperPixels(page.layout);
  const margins = printDialogMarginPixels(page.layout);
  const printableWidth = Math.max(24, paper.width - margins.left - margins.right);
  const printableHeight = Math.max(24, paper.height - margins.top - margins.bottom);
  const rangeLabel = rangeToLabel(page.range);
  content.innerHTML = `
    <div class="print-dialog-preview-paper-shell" data-paper-width="${roundCssNumber(paper.width)}" data-paper-height="${roundCssNumber(paper.height)}">
      <div class="print-dialog-preview-paper" style="width:${roundCssNumber(paper.width)}px;height:${roundCssNumber(paper.height)}px">
        <div class="print-dialog-preview-printable" style="left:${roundCssNumber(margins.left)}px;top:${roundCssNumber(margins.top)}px;width:${roundCssNumber(printableWidth)}px;height:${roundCssNumber(printableHeight)}px">
          ${printSheetHtml(page.sheet, page.range, page.layout, index)}
        </div>
      </div>
    </div>`;
  syncPrintObjectLayerPositions(content);
  label.textContent = pages.length > 1 ? `${index + 1} / ${pages.length}` : "1 / 1";
  const printRangeLabel = rangeToLabel(page.printRange || page.range);
  const rangeSummary = printRangeLabel === rangeLabel
    ? `印刷範囲 ${printRangeLabel}`
    : `印刷範囲 ${printRangeLabel} / 表示 ${rangeLabel}`;
  summary.textContent = `${page.sheet.name || "Sheet"}  ${rangeSummary}  ${page.pageNumber} ページ / ${page.totalPages}  ${page.layout.orientation === "landscape" ? "横" : "縦"} / ${page.layout.paperSize} / ${page.layout.scale}%`;
  syncPrintDialogPreviewNavigation(dialog, index, pages.length);
  requestAnimationFrame(() => {
    syncPrintObjectLayerPositions(content);
    fitPrintDialogPreviewPaper(dialog);
  });
}

function syncPrintDialogPreviewNavigation(dialog, index, count) {
  const prev = dialog?.querySelector?.("[data-data-dialog-action='print-preview-prev']");
  const next = dialog?.querySelector?.("[data-data-dialog-action='print-preview-next']");
  if (prev) prev.disabled = count <= 1 || index <= 0;
  if (next) next.disabled = count <= 1 || index >= count - 1;
}

function fitPrintDialogPreviewPaper(dialog) {
  const viewport = dialog?.querySelector?.("[data-print-preview-viewport]");
  const shell = dialog?.querySelector?.(".print-dialog-preview-paper-shell");
  const paper = dialog?.querySelector?.(".print-dialog-preview-paper");
  if (!viewport || !shell || !paper) return;
  const rawWidth = Number(shell.dataset.paperWidth) || paper.offsetWidth || 1;
  const rawHeight = Number(shell.dataset.paperHeight) || paper.offsetHeight || 1;
  const availableWidth = Math.max(80, viewport.clientWidth - 28);
  const scale = Math.max(0.08, Math.min(1, availableWidth / rawWidth));
  paper.style.transform = `scale(${roundCssNumber(scale)})`;
  shell.style.width = `${roundCssNumber(rawWidth * scale)}px`;
  shell.style.height = `${roundCssNumber(rawHeight * scale)}px`;
}

function movePrintDialogPreview(dialog, delta) {
  if (!dialog) return;
  const count = printPreviewPagesForDialog(dialog).length;
  if (!count) return;
  const current = Math.max(0, Math.min(count - 1, Math.round(Number(dialog.dataset.printPreviewIndex) || 0)));
  dialog.dataset.printPreviewIndex = String(Math.max(0, Math.min(count - 1, current + delta)));
  syncPrintDialogPreview(dialog);
}

function printDialogPaperPixels(layout) {
  const paper = PAGE_LAYOUT_PAPER_SIZES.find((item) => item.value === layout.paperSize) || PAGE_LAYOUT_PAPER_SIZES[0];
  const landscape = layout.orientation === "landscape";
  return {
    width: (landscape ? paper.height : paper.width) * 96,
    height: (landscape ? paper.width : paper.height) * 96,
  };
}

function printDialogMarginPixels(layout) {
  const margins = layout.margins || PAGE_LAYOUT_MARGIN_PRESETS.normal;
  return {
    top: Math.max(0, Number(margins.top) || 0) * 96,
    right: Math.max(0, Number(margins.right) || 0) * 96,
    bottom: Math.max(0, Number(margins.bottom) || 0) * 96,
    left: Math.max(0, Number(margins.left) || 0) * 96,
  };
}

function printPreviewPagesForDialog(dialog) {
  return printTargetsForDialog(dialog)
    .flatMap((target, sheetOrder) => printPreviewPagesForTarget(target, sheetOrder))
    .sort((left, right) => left.sheetOrder - right.sheetOrder || left.pageNumber - right.pageNumber);
}

function printPreviewPagesForTarget(target, sheetOrder = 0) {
  if (!target?.sheet || !target.range) return [];
  const plan = pageBreakPreviewPlan(target.sheet, target.layout, target.range);
  const rows = plan.rows?.segments || [];
  const cols = plan.cols?.segments || [];
  const totalRows = Math.max(1, rows.length);
  const totalCols = Math.max(1, cols.length);
  const pages = [];
  rows.forEach((rowSegment, rowIndex) => {
    cols.forEach((colSegment, colIndex) => {
      const pageNumber = pageBreakPreviewPageNumber(rowIndex + 1, colIndex + 1, totalRows, totalCols, target.layout);
      pages.push({
        sheet: target.sheet,
        sheetOrder,
        layout: target.layout,
        pageNumber,
        totalPages: totalRows * totalCols,
        printRange: { ...target.range },
        range: normalizePrintRange(target.sheet, {
          top: rowSegment.start,
          bottom: rowSegment.end,
          left: colSegment.start,
          right: colSegment.end,
        }),
      });
    });
  });
  return pages.filter((page) => page.range).sort((left, right) => left.pageNumber - right.pageNumber);
}

function printWorkbookFromDialog(dialog) {
  if (!state.model || !dialog) return;
  applyPrintDialogPageSettings(dialog, { render: false });
  if (!prepareWorkbookPrintSurface(dialog)) return;
  closeDataDialog();
  setStatus("印刷を開始しました。");
  requestAnimationFrame(() => {
    try {
      window.print?.();
    } catch (error) {
      console.error("Print failed.", error);
      cleanupWorkbookPrintSurface();
      showMessageBox("印刷を開始できませんでした。ブラウザーの印刷機能を確認してください。", { title: "Cht WebSheet" });
    }
  });
}

function prepareWorkbookPrintSurface(dialog) {
  const targets = printTargetsForDialog(dialog);
  const pages = printPagesForTargets(targets);
  if (!pages.length) {
    showMessageBox("印刷する範囲がありません。", { title: "Cht WebSheet" });
    return false;
  }
  cleanupWorkbookPrintSurface();
  const surface = document.createElement("div");
  surface.id = "workbookPrintSurface";
  surface.setAttribute("aria-hidden", "true");
  surface.innerHTML = pages.map((page, index) => printWorkbookPageHtml(page, index)).join("");
  document.body.appendChild(surface);
  syncPrintObjectLayerPositions(surface);

  const pageStyle = document.createElement("style");
  pageStyle.id = "workbookPrintStyle";
  pageStyle.textContent = workbookPrintPageStyle(pages[0].layout);
  document.head.appendChild(pageStyle);

  document.body.classList.add("is-printing-workbook");
  ensureWorkbookPrintAfterPrintListener();
  scheduleWorkbookPrintSurfaceCleanup();
  requestAnimationFrame(() => syncPrintObjectLayerPositions(surface));
  return true;
}

function printPagesForTargets(targets = []) {
  return (targets || [])
    .flatMap((target, sheetOrder) => printPreviewPagesForTarget(target, sheetOrder))
    .sort((left, right) => left.sheetOrder - right.sheetOrder || left.pageNumber - right.pageNumber);
}

function ensureWorkbookPrintAfterPrintListener() {
  if (ensureWorkbookPrintAfterPrintListener.bound) return;
  window.addEventListener("afterprint", cleanupWorkbookPrintSurface);
  ensureWorkbookPrintAfterPrintListener.bound = true;
}

function scheduleWorkbookPrintSurfaceCleanup() {
  if (state.printSurfaceCleanupTimer) clearTimeout(state.printSurfaceCleanupTimer);
  state.printSurfaceCleanupTimer = window.setTimeout(() => cleanupWorkbookPrintSurface(), 120000);
}

function cleanupWorkbookPrintSurface() {
  if (state.printSurfaceCleanupTimer) {
    clearTimeout(state.printSurfaceCleanupTimer);
    state.printSurfaceCleanupTimer = null;
  }
  document.body.classList.remove("is-printing-workbook");
  document.getElementById("workbookPrintSurface")?.remove();
  document.getElementById("workbookPrintStyle")?.remove();
}

function printTargetsForDialog(dialog) {
  const scope = dialog?.querySelector("[data-data-field='printScope']")?.value || "active";
  if (scope === "workbook") {
    return visibleSheetIndexes()
      .map((sheetIndex) => {
        const sheet = state.model?.sheets?.[sheetIndex];
        return sheet ? printTargetForSheet(sheet, dialog) : null;
      })
      .filter(Boolean);
  }
  const sheet = activeSheet();
  if (!sheet) return [];
  if (scope === "selection") {
    const range = printRangeForSelection(sheet);
    return range ? [{ sheet, range, layout: printLayoutForDialog(sheet, dialog) }] : [];
  }
  return selectedSheetIndexesForPrint()
    .map((sheetIndex) => {
      const targetSheet = state.model?.sheets?.[sheetIndex];
      return targetSheet ? printTargetForSheet(targetSheet, dialog) : null;
    })
    .filter(Boolean);
}

function selectedSheetIndexesForPrint() {
  if (!state.model?.sheets?.length) return [];
  const visible = new Set(visibleSheetIndexes());
  const selected = [...new Set(state.selectedSheetIndexes || [])]
    .filter((sheetIndex) => visible.has(sheetIndex) && state.model.sheets[sheetIndex]);
  if (selected.length > 1) return selected;
  return visible.has(state.activeSheetIndex) && state.model.sheets[state.activeSheetIndex]
    ? [state.activeSheetIndex]
    : [];
}

function printTargetForSheet(sheet, dialog = null) {
  const layout = printLayoutForDialog(sheet, dialog);
  const range = printRangeForSheet(sheet, layout);
  return range ? { sheet, range, layout: normalizedPageLayoutSettings(layout, sheet) } : null;
}

function printLayoutForDialog(sheet, dialog = null) {
  const layout = normalizedPageLayoutSettings(sheet?.pageLayout, sheet);
  if (!dialog) return layout;
  return {
    ...layout,
    ...printDialogPageSettings(dialog),
  };
}

function printRangeForSheet(sheet, layout = ensurePageLayoutSettings(sheet)) {
  return normalizePrintRange(sheet, layout.printArea?.range || sheetUsedRangeForPrint(sheet) || { top: 1, left: 1, bottom: 1, right: 1 });
}

function printRangeForSelection(sheet) {
  const ranges = activeSelectionRanges();
  const materialized = unionMaterializedRanges(materializedRangesForSheet(sheet, ranges, state.activeSheetIndex), state.activeSheetIndex);
  if (!materialized) return printRangeForSheet(sheet);
  const used = sheetUsedRangeForPrint(sheet);
  const range = { ...materialized };
  if (used) {
    if (range.fullRow) {
      range.left = used.left;
      range.right = used.right;
    }
    if (range.fullColumn) {
      range.top = used.top;
      range.bottom = used.bottom;
    }
  }
  return normalizePrintRange(sheet, range);
}

function sheetUsedRangeForPrint(sheet) {
  const ranges = [];
  const used = sheetUsedRange(sheet);
  if (used) ranges.push(used);
  if (sheet?.autoFilter?.range) ranges.push(sheet.autoFilter.range);
  (sheet?.images || []).forEach((image) => {
    if (image?.hidden) return;
    const range = imageRangeForPrint(sheet, image);
    if (range) ranges.push(range);
  });
  if (!ranges.length) return null;
  return {
    top: Math.min(...ranges.map((range) => range.top)),
    left: Math.min(...ranges.map((range) => range.left)),
    bottom: Math.max(...ranges.map((range) => range.bottom)),
    right: Math.max(...ranges.map((range) => range.right)),
  };
}

function imageRangeForPrint(sheet, image) {
  const box = imageBoxToPixels(sheet, image);
  if (!box) return null;
  const top = sheetIndexFromPixel(sheet, "row", box.top) || 1;
  const left = sheetIndexFromPixel(sheet, "col", box.left) || 1;
  const bottom = sheetIndexFromPixel(sheet, "row", box.top + box.height) || top;
  const right = sheetIndexFromPixel(sheet, "col", box.left + box.width) || left;
  return normalizePrintRange(sheet, {
    top: Math.min(top, bottom),
    left: Math.min(left, right),
    bottom: Math.max(top, bottom),
    right: Math.max(left, right),
  });
}

function normalizePrintRange(sheet, range) {
  if (!sheet || !range) return null;
  const rowCount = Math.max(1, Number(sheet.rowCount || sheet.rows?.length || 1));
  const colCount = Math.max(1, Number(sheet.colCount || sheet.columns?.length || 1));
  const top = Math.max(1, Math.min(rowCount, Math.round(Number(range.top) || 1)));
  const left = Math.max(1, Math.min(colCount, Math.round(Number(range.left) || 1)));
  const bottom = Math.max(top, Math.min(rowCount, Math.round(Number(range.bottom) || top)));
  const right = Math.max(left, Math.min(colCount, Math.round(Number(range.right) || left)));
  return { sheetIndex: state.model?.sheets?.indexOf(sheet) ?? state.activeSheetIndex, top, left, bottom, right };
}

function workbookPrintPageStyle(layout) {
  const paper = PAGE_LAYOUT_PAPER_SIZES.find((item) => item.value === layout.paperSize) || PAGE_LAYOUT_PAPER_SIZES[0];
  const size = `${paper.value} ${layout.orientation === "landscape" ? "landscape" : "portrait"}`;
  return `@page{size:${size};margin:0;}`;
}

function printWorkbookPageHtml(page, index = 0) {
  const paper = printDialogPaperPixels(page.layout);
  const margins = printDialogMarginPixels(page.layout);
  const printableWidth = Math.max(24, paper.width - margins.left - margins.right);
  const printableHeight = Math.max(24, paper.height - margins.top - margins.bottom);
  return `
    <section class="workbook-print-page" data-print-page="${index + 1}" style="--print-paper-width:${roundCssNumber(paper.width)}px;--print-paper-height:${roundCssNumber(paper.height)}px;width:${roundCssNumber(paper.width)}px;height:${roundCssNumber(paper.height)}px">
      <div class="workbook-print-page-printable" style="left:${roundCssNumber(margins.left)}px;top:${roundCssNumber(margins.top)}px;width:${roundCssNumber(printableWidth)}px;height:${roundCssNumber(printableHeight)}px">
        ${printSheetHtml(page.sheet, page.range, page.layout, index, { materializeScale: true })}
      </div>
    </section>`;
}

function printSheetHtml(sheet, range, layout, index = 0, options = {}) {
  return withDisplayCalculationCache(sheet, () => {
    const printRows = printRowIndexes(sheet, range);
    const printCols = printColumnIndexes(sheet, range);
    const rawWidth = printCols.reduce((total, col) => total + printColumnWidth(sheet, col), layout.printHeadings ? rowHeaderWidthForSheet(sheet) : 0);
    const rawHeight = printRows.reduce((total, row) => total + printRowHeight(sheet, row), layout.printHeadings ? COLUMN_HEADER_HEIGHT : 0);
    const scale = printSheetEffectiveScale(sheet, range, layout);
    const renderScale = options.materializeScale ? scale : 1;
    const transformScale = options.materializeScale ? 1 : scale;
    const width = Math.max(1, rawWidth * renderScale);
    const height = Math.max(1, rawHeight * renderScale);
    const scaledWidth = Math.max(1, rawWidth * scale);
    const scaledHeight = Math.max(1, rawHeight * scale);
    const classes = [
      "workbook-print-sheet",
      layout.blackAndWhite ? "is-black-white" : "",
      index === 0 ? "is-first" : "",
    ].filter(Boolean).join(" ");
    return `
      <section class="${classes}" data-print-sheet="${escapeAttr(sheet.name || "Sheet")}" style="--print-scale:${roundCssNumber(transformScale)};--print-render-scale:${roundCssNumber(renderScale)};--print-effective-scale:${roundCssNumber(scale)};--print-sheet-width:${roundCssNumber(scaledWidth)}px;--print-sheet-height:${roundCssNumber(scaledHeight)}px;width:${roundCssNumber(scaledWidth)}px;min-height:${roundCssNumber(scaledHeight)}px">
        <div class="workbook-print-sheet-grid" data-print-range-top="${range.top}" data-print-range-left="${range.left}" data-print-range-bottom="${range.bottom}" data-print-range-right="${range.right}" style="width:${roundCssNumber(width)}px;height:${roundCssNumber(height)}px">
          ${printSheetTableHtml(sheet, range, layout, printRows, printCols, renderScale)}
          ${printSheetObjectsHtml(sheet, range, layout, renderScale)}
        </div>
      </section>`;
  });
}

function printSheetEffectiveScale(sheet, printRange, layout) {
  const baseScale = Math.max(0.1, Math.min(4, Number(layout.scale || 100) / 100));
  const pageSize = printRangeContentSize(sheet, printRange, layout);
  const printable = printLayoutPrintablePixels(layout);
  let scale = baseScale;
  const previewPadding = 0.94;
  const { fitToWidth, fitToHeight, active } = pageLayoutFitTargets(layout);
  if (fitToWidth > 0 || (!active && pageSize.width * scale > printable.width * previewPadding)) {
    scale = Math.min(scale, (printable.width * previewPadding) / Math.max(1, pageSize.width));
  }
  if (fitToHeight > 0 || (!active && pageSize.height * scale > printable.height * previewPadding)) {
    scale = Math.min(scale, (printable.height * previewPadding) / Math.max(1, pageSize.height));
  }
  return Math.max(0.1, Math.min(4, scale));
}

function pageLayoutFitTargets(layout = {}) {
  if (layout?.fitToPage !== true) return { fitToWidth: 0, fitToHeight: 0, active: false };
  const fitToWidth = layout.fitToWidth !== "auto" ? Math.max(1, Number(layout.fitToWidth) || 0) : 0;
  const fitToHeight = layout.fitToHeight !== "auto" ? Math.max(1, Number(layout.fitToHeight) || 0) : 0;
  return { fitToWidth, fitToHeight, active: fitToWidth > 0 || fitToHeight > 0 };
}

function printRangeContentSize(sheet, range, layout) {
  const normalized = normalizePrintRange(sheet, range);
  if (!normalized) return { width: 1, height: 1 };
  const cols = printColumnIndexes(sheet, normalized);
  const rows = printRowIndexes(sheet, normalized);
  return {
    width: cols.reduce((total, col) => total + printColumnWidth(sheet, col), layout.printHeadings ? rowHeaderWidthForSheet(sheet) : 0),
    height: rows.reduce((total, row) => total + printRowHeight(sheet, row), layout.printHeadings ? COLUMN_HEADER_HEIGHT : 0),
  };
}

function printLayoutPrintablePixels(layout) {
  const paper = PAGE_LAYOUT_PAPER_SIZES.find((item) => item.value === layout.paperSize) || PAGE_LAYOUT_PAPER_SIZES[0];
  const landscape = layout.orientation === "landscape";
  const paperWidth = landscape ? paper.height : paper.width;
  const paperHeight = landscape ? paper.width : paper.height;
  const margins = layout.margins || PAGE_LAYOUT_MARGIN_PRESETS.normal;
  return {
    width: Math.max(24, (paperWidth - Number(margins.left || 0) - Number(margins.right || 0)) * 96),
    height: Math.max(24, (paperHeight - Number(margins.top || 0) - Number(margins.bottom || 0)) * 96),
  };
}

function printRowIndexes(sheet, range) {
  const rows = [];
  for (let row = range.top; row <= range.bottom; row += 1) {
    if (sheet.rows?.[row - 1]?.hidden) continue;
    rows.push(row);
  }
  return rows.length ? rows : [range.top];
}

function printColumnIndexes(sheet, range) {
  const cols = [];
  for (let col = range.left; col <= range.right; col += 1) {
    if (sheet.columns?.[col - 1]?.hidden) continue;
    cols.push(col);
  }
  return cols.length ? cols : [range.left];
}

function printRowHeight(sheet, row) {
  return Math.max(1, Number(sheet.rows?.[row - 1]?.height || sheet.defaultRowHeight || rowHeightToPixels(15)));
}

function printColumnWidth(sheet, col) {
  return Math.max(1, Number(sheet.columns?.[col - 1]?.width || sheet.defaultColumnWidth || columnWidthToPixels(8.43)));
}

function printRenderScale(value) {
  const number = Number(value);
  return Number.isFinite(number) && number > 0 ? number : 1;
}

function printSheetTableHtml(sheet, range, layout, printRows, printCols, renderScale = 1) {
  const sheetId = getSheetId(sheet.name);
  const mergeMaps = buildPrintMergeMaps(sheet, range, printRows, printCols);
  const scaleValue = printRenderScale(renderScale);
  const colgroup = [
    layout.printHeadings ? `<col class="workbook-print-row-heading-col" data-print-col-heading="true" data-print-col-width="${roundCssNumber(rowHeaderWidthForSheet(sheet) * scaleValue)}" style="width:${roundCssNumber(rowHeaderWidthForSheet(sheet) * scaleValue)}px">` : "",
    ...printCols.map((col) => `<col data-print-col="${col}" data-print-col-width="${roundCssNumber(printColumnWidth(sheet, col) * scaleValue)}" style="width:${roundCssNumber(printColumnWidth(sheet, col) * scaleValue)}px">`),
  ].filter(Boolean).join("");
  const rows = [];
  if (layout.printHeadings) {
    const headingHeight = COLUMN_HEADER_HEIGHT * scaleValue;
    rows.push(`<tr class="workbook-print-column-heading-row" data-print-row-heading="true" data-print-row-height="${roundCssNumber(headingHeight)}" style="height:${roundCssNumber(headingHeight)}px"><th class="workbook-print-corner-heading"></th>${printCols.map((col) => `<th class="workbook-print-column-heading">${escapeHtml(columnName(col))}</th>`).join("")}</tr>`);
  }
  printRows.forEach((row) => {
    const cells = [];
    if (layout.printHeadings) cells.push(`<th class="workbook-print-row-heading">${row}</th>`);
    printCols.forEach((col) => {
      const cellHtml = printCellHtml(sheet, mergeMaps, sheetId, row, col, range, printRows, printCols, layout, scaleValue);
      if (cellHtml) cells.push(cellHtml);
    });
    const rowHeight = printRowHeight(sheet, row) * scaleValue;
    rows.push(`<tr data-print-row="${row}" data-print-row-height="${roundCssNumber(rowHeight)}" style="height:${roundCssNumber(rowHeight)}px">${cells.join("")}</tr>`);
  });
  const classes = `workbook-print-table${layout.printGridLines ? " has-gridlines" : ""}`;
  return `<table class="${classes}"><colgroup>${colgroup}</colgroup><tbody>${rows.join("")}</tbody></table>`;
}

function printCellHtml(sheet, mergeMaps, sheetId, row, col, range, printRows, printCols, layout, renderScale = 1) {
  const key = cellKey(row, col);
  if (mergeMaps.covered.has(key)) return "";
  const merge = mergeMaps.master.get(key);
  const rowSpan = merge ? countPrintIndexesInRange(printRows, row, Math.min(merge.bottom, range.bottom)) : 1;
  const colSpan = merge ? countPrintIndexesInRange(printCols, col, Math.min(merge.right, range.right)) : 1;
  if (rowSpan <= 0 || colSpan <= 0) return "";
  const sourceRow = merge?.sourceTop || row;
  const sourceCol = merge?.sourceLeft || col;
  const sourceKey = cellKey(sourceRow, sourceCol);
  const sourceCell = sheet.cells?.[sourceKey] || {};
  const cell = merge ? printCellForMergeSlice(sourceCell, merge) : sourceCell;
  const scaleValue = printRenderScale(renderScale);
  const cellHeight = printCellSpanHeight(sheet, printRows, row, rowSpan) * scaleValue;
  const showMergedContent = !merge || (sourceRow === row && sourceCol === col);
  const display = showMergedContent
    ? (state.showFormulas && cell.formula ? cell.formula : getDisplayForCell(sheet, sheetId, sourceRow, sourceCol))
    : "";
  const overflowWidth = printCellOverflowWidth(sheet, mergeMaps, row, col, colSpan, cell, display, range, layout, scaleValue);
  const suppressGridSides = merge ? printMergeSliceSuppressedSides(merge) : null;
  const attrs = [
    overflowWidth ? `class="workbook-print-cell-overflow"` : "",
    rowSpan > 1 ? `rowspan="${rowSpan}"` : "",
    colSpan > 1 ? `colspan="${colSpan}"` : "",
    `style="${escapeAttr(printCellStyle(sheet, cell, cellHeight, layout, scaleValue, suppressGridSides))}"`,
  ].filter(Boolean).join(" ");
  return `<td ${attrs}><div class="workbook-print-cell-content" style="${escapeAttr(printCellContentStyle(sheet, cell, cellHeight, overflowWidth))}"><span class="workbook-print-cell-text">${printCellContentHtml(display)}</span></div></td>`;
}

function buildPrintMergeMaps(sheet, range, printRows, printCols) {
  const master = new Map();
  const covered = new Set();
  const coveredToMaster = new Map();
  const rowSet = new Set(printRows || []);
  const colSet = new Set(printCols || []);
  (sheet?.merges || []).forEach((merge) => {
    if (!merge || !rangesIntersect(merge, range)) return;
    const visibleRows = [];
    for (let row = Math.max(merge.top, range.top); row <= Math.min(merge.bottom, range.bottom); row += 1) {
      if (rowSet.has(row)) visibleRows.push(row);
    }
    const visibleCols = [];
    for (let col = Math.max(merge.left, range.left); col <= Math.min(merge.right, range.right); col += 1) {
      if (colSet.has(col)) visibleCols.push(col);
    }
    if (!visibleRows.length || !visibleCols.length) return;
    const visible = {
      top: visibleRows[0],
      left: visibleCols[0],
      bottom: visibleRows[visibleRows.length - 1],
      right: visibleCols[visibleCols.length - 1],
      sourceTop: merge.top,
      sourceLeft: merge.left,
      sourceBottom: merge.bottom,
      sourceRight: merge.right,
    };
    const masterKey = cellKey(visible.top, visible.left);
    master.set(masterKey, visible);
    visibleRows.forEach((row) => {
      visibleCols.forEach((col) => {
        const key = cellKey(row, col);
        if (key === masterKey) return;
        covered.add(key);
        coveredToMaster.set(key, masterKey);
      });
    });
  });
  return { master, covered, coveredToMaster };
}

function printCellForMergeSlice(cell, merge) {
  if (!merge || !cell) return cell || {};
  const borders = { ...(cell.borders || {}) };
  if (merge.top > merge.sourceTop) delete borders.top;
  if (merge.bottom < merge.sourceBottom) delete borders.bottom;
  if (merge.left > merge.sourceLeft) delete borders.left;
  if (merge.right < merge.sourceRight) delete borders.right;
  return { ...cell, borders };
}

function printMergeSliceSuppressedSides(merge) {
  const sides = new Set();
  if (!merge) return sides;
  if (merge.top > merge.sourceTop) sides.add("top");
  if (merge.bottom < merge.sourceBottom) sides.add("bottom");
  if (merge.left > merge.sourceLeft) sides.add("left");
  if (merge.right < merge.sourceRight) sides.add("right");
  return sides;
}

function countPrintIndexesInRange(indexes, start, end) {
  return indexes.filter((index) => index >= start && index <= end).length;
}

function printCellSpanHeight(sheet, printRows, row, rowSpan) {
  const startIndex = printRows.indexOf(row);
  const rows = startIndex >= 0 ? printRows.slice(startIndex, startIndex + Math.max(1, rowSpan)) : [row];
  return Math.max(1, rows.reduce((total, rowIndex) => total + printRowHeight(sheet, rowIndex), 0));
}

function printCellSpanWidth(sheet, col, colSpan) {
  let width = 0;
  for (let colIndex = col; colIndex < col + Math.max(1, colSpan); colIndex += 1) {
    width += printColumnWidth(sheet, colIndex);
  }
  return Math.max(1, width);
}

function printCellOverflowWidth(sheet, mergeMaps, row, col, colSpan, cell, display, range, layout = {}, renderScale = 1) {
  const scaleValue = printRenderScale(renderScale);
  const overflowWidth = textOverflowWidth(sheet, mergeMaps, row, col, colSpan, cell, display);
  if (!overflowWidth) return null;
  const currentWidth = printCellSpanWidth(sheet, col, colSpan);
  if (!layout?.printArea?.range) return Math.max(currentWidth, overflowWidth) * scaleValue;
  const rangeRight = Math.max(col + colSpan - 1, Math.min(sheet.colCount, Number(range?.right) || col + colSpan - 1));
  const pageWidth = widthBetweenColumns(sheet, col, rangeRight);
  return Math.max(currentWidth, Math.min(overflowWidth, pageWidth || currentWidth)) * scaleValue;
}

function printCellStyle(sheet, cell, rowHeight, layout, renderScale = 1, suppressGridSides = null) {
  const scaleValue = printRenderScale(renderScale);
  const style = legacyExcelCellStyle(sheet, cell, rowHeight, scaleValue);
  if (!layout.printGridLines) return style;
  const borders = cell?.borders || {};
  const extra = {};
  CELL_BORDER_SIDES.forEach((side) => {
    if (suppressGridSides?.has?.(side)) return;
    if (borders[side]) return;
    const cssSide = side === "top" ? "borderTop" : side === "right" ? "borderRight" : side === "bottom" ? "borderBottom" : "borderLeft";
    extra[cssSide] = `${roundCssNumber(Math.max(0.5, scaleValue))}px solid #d9e2ec`;
  });
  return [style, styleObjectToString(extra)].filter(Boolean).join(";");
}

function printCellContentStyle(sheet, cell, height, overflowWidth = null) {
  const css = cellEffectiveCss(sheet, cell);
  const justifyContent = css.verticalAlign === "top"
    ? "flex-start"
    : css.verticalAlign === "bottom"
      ? "flex-end"
      : "center";
  const width = overflowWidth ? `${Math.max(1, Math.round(Number(overflowWidth) || 1))}px` : "100%";
  return styleObjectToString({
    height: `${Math.max(1, Math.round(Number(height) || 1))}px`,
    maxHeight: `${Math.max(1, Math.round(Number(height) || 1))}px`,
    justifyContent,
    lineHeight: "1.2",
    whiteSpace: css.whiteSpace === "pre-wrap" ? "pre-wrap" : "nowrap",
    width,
    maxWidth: overflowWidth ? "none" : "100%",
  });
}

function printCellContentHtml(display) {
  return escapeHtml(display ?? "").replace(/\r\n|\r|\n/g, "<br>");
}

function printSheetObjectsHtml(sheet, range, layout, renderScale = 1) {
  if (sheet?.showObjects === false) return "";
  const origin = printRangePixelBounds(sheet, range);
  const scaleValue = printRenderScale(renderScale);
  const objects = [
    printSheetImagesHtml(sheet, range, layout, origin, scaleValue),
    printSheetInkHtml(sheet, range, layout, origin, scaleValue),
  ].filter(Boolean).join("");
  if (!objects) return "";
  return `<div class="workbook-print-object-layer" aria-hidden="true">${objects}</div>`;
}

function printRangePixelBounds(sheet, range) {
  const left = coordinateToPixels(sheet, "col", range.left - 1);
  const top = coordinateToPixels(sheet, "row", range.top - 1);
  const right = coordinateToPixels(sheet, "col", range.right);
  const bottom = coordinateToPixels(sheet, "row", range.bottom);
  return { left, top, right, bottom, width: Math.max(1, right - left), height: Math.max(1, bottom - top) };
}

function printHeadingOffsets(sheet, layout) {
  return {
    left: layout.printHeadings ? rowHeaderWidthForSheet(sheet) : 0,
    top: layout.printHeadings ? COLUMN_HEADER_HEIGHT : 0,
  };
}

function printSheetImagesHtml(sheet, range, layout, origin = printRangePixelBounds(sheet, range), renderScale = 1) {
  if (!sheet.images?.length) return "";
  const offsets = printHeadingOffsets(sheet, layout);
  const scaleValue = printRenderScale(renderScale);
  return sheet.images
    .map((image) => printImageHtml(sheet, image, origin, offsets, scaleValue))
    .filter(Boolean)
    .join("");
}

function printImageHtml(sheet, image, origin, offsets, renderScale = 1) {
  if (image?.hidden) return "";
  const box = imageBoxToPixels(sheet, image);
  if (!box) return "";
  const visualBounds = imageVisualBoundsToPixels(image, box);
  if (!pixelBoxesIntersect(visualBounds, origin)) return "";
  const scaleValue = printRenderScale(renderScale);
  const relativeBox = {
    left: (box.left - origin.left + offsets.left) * scaleValue,
    top: (box.top - origin.top + offsets.top) * scaleValue,
    width: box.width * scaleValue,
    height: box.height * scaleValue,
  };
  const style = `${imageBoxBaseStyle(image, relativeBox)}${objectVisualStyle(image)};position:absolute`;
  return imageObjectHtml(image, style, "", printObjectPositionAttrs(relativeBox));
}

function printObjectPositionAttrs(box) {
  return [
    `data-print-object="true"`,
    `data-print-object-left="${roundCssNumber(box.left)}"`,
    `data-print-object-top="${roundCssNumber(box.top)}"`,
    `data-print-object-width="${roundCssNumber(box.width)}"`,
    `data-print-object-height="${roundCssNumber(box.height)}"`,
  ].join(" ");
}

function syncPrintObjectLayerPositions(root = document) {
  if (!root?.querySelectorAll) return;
  root.querySelectorAll(".workbook-print-sheet-grid").forEach((grid) => {
    const rows = printRowAxisSegments(grid);
    const cols = printColumnAxisSegments(grid);
    if (!rows.length && !cols.length) return;
    grid.querySelectorAll("[data-print-object='true']").forEach((object) => {
      const left = Number(object.dataset.printObjectLeft);
      const top = Number(object.dataset.printObjectTop);
      const width = Number(object.dataset.printObjectWidth);
      const height = Number(object.dataset.printObjectHeight);
      if (![left, top, width, height].every(Number.isFinite)) return;
      const mappedLeft = cols.length ? mapPrintAxisCoordinate(cols, left) : left;
      const mappedRight = cols.length ? mapPrintAxisCoordinate(cols, left + width) : left + width;
      const mappedTop = rows.length ? mapPrintAxisCoordinate(rows, top) : top;
      const mappedBottom = rows.length ? mapPrintAxisCoordinate(rows, top + height) : top + height;
      object.style.left = `${roundCssNumber(mappedLeft)}px`;
      object.style.top = `${roundCssNumber(mappedTop)}px`;
      object.style.width = `${roundCssNumber(Math.max(1, mappedRight - mappedLeft))}px`;
      object.style.height = `${roundCssNumber(Math.max(1, mappedBottom - mappedTop))}px`;
    });
  });
}

function printRowAxisSegments(grid) {
  const rows = [...grid.querySelectorAll("tr[data-print-row-height]")];
  return printAxisSegments(rows.map((row) => ({
    expected: Number(row.dataset.printRowHeight) || row.offsetHeight || 1,
    actual: row.offsetHeight || Number(row.getBoundingClientRect?.().height) || Number(row.dataset.printRowHeight) || 1,
  })));
}

function printColumnAxisSegments(grid) {
  const cols = [...grid.querySelectorAll("col[data-print-col-width]")];
  const expectedWidths = cols.map((col) => Math.max(1, Number(col.dataset.printColWidth) || 1));
  if (!expectedWidths.length) return [];
  const expectedTotal = expectedWidths.reduce((sum, width) => sum + width, 0);
  const table = grid.querySelector(".workbook-print-table");
  const actualTotal = Math.max(1, Number(table?.offsetWidth) || expectedTotal);
  const ratio = actualTotal / Math.max(1, expectedTotal);
  return printAxisSegments(expectedWidths.map((width) => ({ expected: width, actual: width * ratio })));
}

function printAxisSegments(items) {
  let expectedStart = 0;
  let actualStart = 0;
  return items.map((item) => {
    const expectedSize = Math.max(1, Number(item.expected) || 1);
    const actualSize = Math.max(1, Number(item.actual) || expectedSize);
    const segment = {
      expectedStart,
      expectedEnd: expectedStart + expectedSize,
      actualStart,
      actualEnd: actualStart + actualSize,
      expectedSize,
      actualSize,
    };
    expectedStart += expectedSize;
    actualStart += actualSize;
    return segment;
  });
}

function mapPrintAxisCoordinate(segments, value) {
  const coordinate = Math.max(0, Number(value) || 0);
  if (!segments.length) return coordinate;
  const first = segments[0];
  if (coordinate <= first.expectedStart) return first.actualStart + (coordinate - first.expectedStart);
  for (const segment of segments) {
    if (coordinate <= segment.expectedEnd) {
      const ratio = Math.max(0, Math.min(1, (coordinate - segment.expectedStart) / segment.expectedSize));
      return segment.actualStart + ratio * segment.actualSize;
    }
  }
  const last = segments[segments.length - 1];
  return last.actualEnd + (coordinate - last.expectedEnd);
}

function printSheetInkHtml(sheet, range, layout, origin = printRangePixelBounds(sheet, range), renderScale = 1) {
  const strokes = normalizeInkStrokes(sheet?.inkStrokes);
  if (!strokes.length) return "";
  const offsets = printHeadingOffsets(sheet, layout);
  const scaleValue = printRenderScale(renderScale);
  const paths = strokes
    .filter((stroke) => pixelBoxesIntersect(inkStrokeBoundingBox(stroke), origin))
    .map((stroke) => inkStrokeSvg(stroke, false))
    .filter(Boolean)
    .join("");
  if (!paths) return "";
  const style = [
    `left:${roundCssNumber(offsets.left * scaleValue)}px`,
    `top:${roundCssNumber(offsets.top * scaleValue)}px`,
    `width:${roundCssNumber(origin.width * scaleValue)}px`,
    `height:${roundCssNumber(origin.height * scaleValue)}px`,
  ].join(";");
  return `<svg class="workbook-print-ink-layer" style="${escapeAttr(style)}" viewBox="${roundCssNumber(origin.left)} ${roundCssNumber(origin.top)} ${roundCssNumber(origin.width)} ${roundCssNumber(origin.height)}">${paths}</svg>`;
}

function handlePageSetupTabClick(event) {
  const tab = event.currentTarget;
  const dialog = tab.closest('[data-data-dialog="page-setup"]');
  if (!dialog) return;
  const id = tab.dataset.pageSetupTab;
  dialog.querySelectorAll("[data-page-setup-tab]").forEach((item) => item.classList.toggle("is-active", item === tab));
  dialog.querySelectorAll("[data-page-setup-panel]").forEach((panel) => panel.classList.toggle("is-active", panel.dataset.pageSetupPanel === id));
}

function applyPageSetupDialog(dialog) {
  const sheet = activeSheet();
  if (!sheet) return;
  const printAreaText = String(dialog.querySelector("[data-page-setup-field='printArea']")?.value || "").trim();
  const titleRowsText = String(dialog.querySelector("[data-page-setup-field='printTitleRows']")?.value || "").trim();
  const titleColumnsText = String(dialog.querySelector("[data-page-setup-field='printTitleColumns']")?.value || "").trim();
  const parsedPrintArea = printAreaText ? parsePageSetupRangeLabel(printAreaText, sheet) : null;
  const titleRows = titleRowsText ? parsePageSetupRangeLabel(titleRowsText, sheet) : null;
  const titleColumns = titleColumnsText ? parsePageSetupRangeLabel(titleColumnsText, sheet) : null;
  if (printAreaText && !parsedPrintArea) {
    showMessageBox("印刷範囲の参照が正しくありません。", { title: "Cht WebSheet" });
    return;
  }
  if (titleRowsText && !titleRows) {
    showMessageBox("タイトル行の参照が正しくありません。", { title: "Cht WebSheet" });
    return;
  }
  if (titleColumnsText && !titleColumns) {
    showMessageBox("タイトル列の参照が正しくありません。", { title: "Cht WebSheet" });
    return;
  }
  commitPageLayoutChange((layout) => {
    layout.orientation = dialog.querySelector("[data-page-setup-field='orientation']:checked")?.value || dialog.querySelector("[data-page-setup-field='orientation']")?.value || layout.orientation;
    layout.paperSize = dialog.querySelector("[data-page-setup-field='paperSize']")?.value || layout.paperSize;
    layout.scale = Number(dialog.querySelector("[data-page-setup-field='scale']")?.value) || layout.scale;
    layout.fitToWidth = dialog.querySelector("[data-page-setup-field='fitToWidth']")?.value || layout.fitToWidth;
    layout.fitToHeight = dialog.querySelector("[data-page-setup-field='fitToHeight']")?.value || layout.fitToHeight;
    layout.fitToPage = layout.fitToWidth !== "auto" || layout.fitToHeight !== "auto";
    layout.firstPageNumber = Number(dialog.querySelector("[data-page-setup-field='firstPageNumber']")?.value) || layout.firstPageNumber;
    layout.pageOrder = dialog.querySelector("[data-page-setup-field='pageOrder']")?.value || layout.pageOrder;
    layout.comments = dialog.querySelector("[data-page-setup-field='comments']")?.value || layout.comments;
    layout.cellErrors = dialog.querySelector("[data-page-setup-field='cellErrors']")?.value || layout.cellErrors;
    layout.printArea = parsedPrintArea ? { label: rangeToLabel(parsedPrintArea), range: parsedPrintArea } : null;
    layout.printTitles = {
      rows: normalizePageSetupPrintTitleRows(titleRows, sheet),
      cols: normalizePageSetupPrintTitleColumns(titleColumns, sheet),
    };
    layout.margins = { ...(layout.margins || {}) };
    dialog.querySelectorAll("[data-page-setup-margin]").forEach((input) => {
      const key = input.dataset.pageSetupMargin;
      layout.margins[key] = parsePageSetupMarginValue(input, key);
    });
    layout.printGridLines = Boolean(dialog.querySelector("[data-page-setup-check='printGridLines']")?.checked);
    layout.printHeadings = Boolean(dialog.querySelector("[data-page-setup-check='printHeadings']")?.checked);
    layout.centerHorizontal = Boolean(dialog.querySelector("[data-page-setup-check='centerHorizontal']")?.checked);
    layout.centerVertical = Boolean(dialog.querySelector("[data-page-setup-check='centerVertical']")?.checked);
    layout.blackAndWhite = Boolean(dialog.querySelector("[data-page-setup-check='blackAndWhite']")?.checked);
    layout.draftQuality = Boolean(dialog.querySelector("[data-page-setup-check='draftQuality']")?.checked);
    layout.headerFooter = {
      header: String(dialog.querySelector("[data-page-setup-field='headerText']")?.value || ""),
      footer: String(dialog.querySelector("[data-page-setup-field='footerText']")?.value || ""),
    };
    sheet.headerFooter = headerFooterSettingsFromSimpleText(layout.headerFooter.header, layout.headerFooter.footer, sheet.headerFooter);
  }, "ページ設定", "ページ設定を更新しました。");
  closeDataDialog();
}

function parsePageSetupRangeLabel(label, sheet = activeSheet()) {
  const parsed = pageSetupReferenceParts(label);
  if (!parsed?.text) return null;
  if (parsed.sheetName) {
    const expected = sheet?.name || activeSheet()?.name || "";
    if (expected && parsed.sheetName !== expected) return null;
  }
  const text = parsed.text.replace(/\$/g, "").trim().toUpperCase();
  const rowOnly = text.match(/^(\d+):(\d+)$/);
  if (rowOnly) {
    const top = Math.max(1, Math.min(Number(rowOnly[1]), Number(rowOnly[2])));
    const bottom = Math.max(top, Math.max(Number(rowOnly[1]), Number(rowOnly[2])));
    return { top, bottom, left: 1, right: sheet.colCount, sheetIndex: state.activeSheetIndex, fullRow: true };
  }
  const columnOnly = text.match(/^([A-Z]+):([A-Z]+)$/);
  if (columnOnly) {
    const left = Math.max(1, Math.min(columnNumber(columnOnly[1]), columnNumber(columnOnly[2])));
    const right = Math.max(left, Math.max(columnNumber(columnOnly[1]), columnNumber(columnOnly[2])));
    return { top: 1, bottom: sheet.rowCount, left, right, sheetIndex: state.activeSheetIndex, fullColumn: true };
  }
  const cell = (value) => {
    const match = String(value || "").trim().match(/^([A-Z]+)(\d+)$/);
    if (!match) return null;
    return { col: Math.max(1, columnNumber(match[1])), row: Math.max(1, Number(match[2])) };
  };
  const [startText, endText = startText] = text.split(":");
  const start = cell(startText);
  const end = cell(endText);
  if (!start || !end) return null;
  return normalizeRange(
    { sheetIndex: state.activeSheetIndex, row: start.row, col: start.col },
    { sheetIndex: state.activeSheetIndex, row: end.row, col: end.col },
  );
}

function pageSetupReferenceParts(label) {
  let text = String(label || "").trim();
  if (!text) return null;
  if (text.startsWith("=")) text = text.slice(1).trim();
  let sheetName = "";
  const bangIndex = pageSetupReferenceBangIndex(text);
  if (bangIndex >= 0) {
    const sheetText = text.slice(0, bangIndex).trim();
    text = text.slice(bangIndex + 1).trim();
    sheetName = unquoteFormulaSheetName(sheetText);
  }
  return { sheetName, text };
}

function pageSetupReferenceBangIndex(text) {
  let inQuote = false;
  for (let index = 0; index < text.length; index += 1) {
    const char = text[index];
    if (char === "'") {
      if (inQuote && text[index + 1] === "'") {
        index += 1;
      } else {
        inQuote = !inQuote;
      }
    } else if (char === "!" && !inQuote) {
      return index;
    }
  }
  return -1;
}

function beginInkDrawingMode(toolKey) {
  cancelShapeDrawing({ silent: true });
  closeRibbonInkEraserMenu();
  if (toolKey === "lasso") {
    state.pendingInkTool = { type: "lasso", label: "なげなわ選択" };
    document.body.classList.add("is-drawing-ink");
    $sheetHost.addClass("is-drawing-ink");
    setStatus("なげなわ選択：オブジェクトを囲むようにドラッグしてください。");
    return;
  }
  const preset = DRAW_INK_TOOLS[toolKey] || DRAW_INK_TOOLS.pen;
  const selectedColor = state.currentInkColor || state.currentInkTool.color || preset.color;
  state.currentInkTool = { ...state.currentInkTool, ...preset, type: toolKey, color: selectedColor };
  state.pendingInkTool = { ...state.currentInkTool };
  document.body.classList.add("is-drawing-ink");
  $sheetHost.addClass("is-drawing-ink");
  syncDrawRibbonButtons();
  setStatus(`${preset.label}：シート上でドラッグして描画してください。`);
}

function beginInkEraserMode(eraserKey = state.currentInkEraser || "stroke") {
  cancelShapeDrawing({ silent: true });
  closeRibbonInkEraserMenu();
  const preset = DRAW_INK_ERASERS[eraserKey] || DRAW_INK_ERASERS.stroke;
  state.currentInkEraser = eraserKey;
  state.pendingInkTool = {
    type: "eraser",
    label: preset.label,
    eraserKey,
    eraserMode: preset.mode,
    eraserRadius: preset.radius,
  };
  document.body.classList.add("is-drawing-ink");
  $sheetHost.addClass("is-drawing-ink");
  syncDrawRibbonButtons();
  const detail = preset.mode === "stroke" ? "インクをクリックまたはドラッグして線全体を削除します。" : "ドラッグした部分だけを削除します。";
  setStatus(`${preset.label}：${detail}`);
}

function cancelInkDrawingMode() {
  state.pendingInkTool = null;
  if (state.inkDrawing?.preview) state.inkDrawing.preview.remove();
  state.inkDrawing = null;
  document.body.classList.remove("is-drawing-ink");
  $sheetHost.removeClass("is-drawing-ink");
  syncDrawRibbonButtons();
}

function setInkColor(colorKey) {
  const color = DRAW_COLOR_PRESETS[colorKey] || DRAW_COLOR_PRESETS.black;
  state.currentInkColor = color;
  state.currentInkTool = { ...state.currentInkTool, color };
  if (state.pendingInkTool && !["eraser", "lasso"].includes(state.pendingInkTool.type)) state.pendingInkTool.color = color;
  syncDrawRibbonButtons();
  setStatus("ペンの色を変更しました。");
}

function setInkWidth(width) {
  state.currentInkTool = { ...state.currentInkTool, width };
  if (state.pendingInkTool && !["eraser", "lasso"].includes(state.pendingInkTool.type)) state.pendingInkTool.width = width;
  setStatus(`ペンの太さを ${width}px に変更しました。`);
}

function syncDrawRibbonButtons() {
  const type = state.pendingInkTool?.type || "";
  ["draw-pen", "draw-pencil", "draw-highlighter", "draw-eraser", "draw-lasso"].forEach((command) => {
    document.querySelector(`[data-ribbon-command="${command}"]`)?.classList.toggle("is-active", command === `draw-${type}`);
  });
  const eraserPreset = DRAW_INK_ERASERS[state.currentInkEraser] || DRAW_INK_ERASERS.stroke;
  const eraserButton = document.querySelector('[data-ribbon-command="draw-eraser"]');
  if (eraserButton) {
    eraserButton.title = eraserPreset.label;
    const label = eraserButton.querySelector("span");
    if (label) label.textContent = eraserPreset.shortLabel || "消しゴム";
  }
  Object.entries(DRAW_COLOR_PRESETS).forEach(([key, color]) => {
    document.querySelector(`[data-ribbon-command="draw-color-${key}"]`)?.classList.toggle("is-active", color.toLowerCase() === String(state.currentInkTool.color || "").toLowerCase());
  });
}

function startInkDrawing(event) {
  const tool = state.pendingInkTool;
  if (!tool || event.button !== 0) return false;
  if (tool.type === "eraser") {
    const sheet = activeSheet();
    if (!ensureSheetProtectionPermission(sheet, "allowEditObjects", "保護されたシートではインクを削除できません。")) return false;
    closeRibbonShapeMenu();
    closeRibbonInkEraserMenu();
    stopSelectionAutoScroll();
    state.inkDrawing = {
      tool: { ...tool },
      pointerId: event.pointerId,
      sheetIndex: state.activeSheetIndex,
      eraserBefore: captureSheetForHistory(sheet),
      eraserChanged: false,
      selectionBefore: activeSelectionRange(),
      selectionBeforeRanges: activeSelectionRanges(),
    };
    eraseInkAtClientPoint(event.clientX, event.clientY, { deferHistory: true });
    try {
      setPointerCaptureSafely(event.currentTarget, event.pointerId);
    } catch {}
    event.preventDefault();
    event.stopPropagation();
    return true;
  }
  const point = sheetPixelFromClientPosition(event.clientX, event.clientY);
  if (!point) return false;
  closeRibbonShapeMenu();
  stopSelectionAutoScroll();
  state.selected = null;
  state.selectionRange = null;
  state.selectionRanges = [];
  state.selectedImage = null;
  state.selectedImages = [];
  state.isSelecting = false;
  state.inkDrawing = {
    tool: { ...tool },
    points: [point],
    pointerId: event.pointerId,
    preview: createInkDrawingPreview(tool),
  };
  $sheetHost.find(".sheet-grid")[0]?.append(state.inkDrawing.preview);
  updateInkDrawingPreview();
  try {
    event.currentTarget.setPointerCapture?.(event.pointerId);
  } catch {}
  event.preventDefault();
  event.stopPropagation();
  return true;
}

function updateInkDrawing(event) {
  const drawing = state.inkDrawing;
  if (!drawing) return;
  if (drawing.pointerId && event.pointerId && drawing.pointerId !== event.pointerId) return;
  if (drawing.tool.type === "eraser") {
    eraseInkAtClientPoint(event.clientX, event.clientY, { deferHistory: true });
    event.preventDefault?.();
    return;
  }
  const point = sheetPixelFromClientPosition(event.clientX, event.clientY, { clampToGrid: true });
  if (!point) return;
  const last = drawing.points.at(-1);
  if (!last || Math.hypot(point.x - last.x, point.y - last.y) >= 2) {
    drawing.points.push(point);
    updateInkDrawingPreview();
  }
  event.preventDefault?.();
}

function finishInkDrawing(event) {
  const drawing = state.inkDrawing;
  if (!drawing) return;
  if (drawing.pointerId && event.pointerId && drawing.pointerId !== event.pointerId) return;
  const tool = drawing.tool;
  if (tool.type === "eraser") {
    state.inkDrawing = null;
    finishInkEraser(drawing);
    event.preventDefault?.();
    return;
  }
  const points = drawing.points.slice();
  drawing.preview?.remove();
  state.inkDrawing = null;
  if (tool.type === "lasso") selectInkObjectsInsideLasso(points);
  else insertInkPathFromPoints(points, tool);
  event.preventDefault?.();
}

function finishInkEraser(drawing) {
  const sheetIndex = Number.isInteger(drawing?.sheetIndex) ? drawing.sheetIndex : state.activeSheetIndex;
  const sheet = state.model?.sheets?.[sheetIndex] || activeSheet();
  if (!drawing?.eraserChanged || !sheet) {
    setStatus("削除するインクがありません。");
    return;
  }
  pushHistory({
    sheetIndex,
    sheetBefore: drawing.eraserBefore,
    sheetAfter: captureSheetForHistory(sheet),
    selectionBefore: drawing.selectionBefore || null,
    selectionAfter: null,
    selectionBeforeRanges: drawing.selectionBeforeRanges || [],
    selectionAfterRanges: [],
    label: "インクの削除",
  });
  setStatus("インクを削除しました。");
}

function createInkDrawingPreview(tool) {
  const preview = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  preview.classList.add("sheet-ink-draft");
  preview.setAttribute("aria-hidden", "true");
  const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
  path.setAttribute("fill", "none");
  path.setAttribute("stroke", tool.color || "#111827");
  path.setAttribute("stroke-width", String(tool.width || 2));
  path.setAttribute("stroke-linecap", "round");
  path.setAttribute("stroke-linejoin", "round");
  path.setAttribute("opacity", String(tool.opacity ?? 1));
  preview.append(path);
  return preview;
}

function updateInkDrawingPreview() {
  const drawing = state.inkDrawing;
  if (!drawing?.preview) return;
  const box = pointListBoundingBox(drawing.points, Math.max(4, drawing.tool.width || 2));
  drawing.preview.setAttribute("viewBox", `${box.left} ${box.top} ${box.width} ${box.height}`);
  Object.assign(drawing.preview.style, {
    left: `${box.left}px`,
    top: `${box.top}px`,
    width: `${box.width}px`,
    height: `${box.height}px`,
  });
  drawing.preview.querySelector("path")?.setAttribute("d", svgPathDFromSheetPoints(drawing.points));
}

function insertInkPathFromPoints(points, tool) {
  if (!points || points.length < 2) return;
  const sheet = activeSheet();
  if (!ensureSheetProtectionPermission(sheet, "allowEditObjects", "保護されたシートではインクを描画できません。")) return;
  const stroke = createInkStrokeFromPoints(points, tool);
  if (!stroke) return;
  const before = captureSheetForHistory(sheet);
  sheet.inkStrokes = normalizeInkStrokes(sheet.inkStrokes);
  sheet.inkStrokes.push(stroke);
  state.selectedInkStrokeIds = [];
  pushHistory({
    sheetIndex: state.activeSheetIndex,
    sheetBefore: before,
    sheetAfter: captureSheetForHistory(sheet),
    selectionBefore: null,
    selectionAfter: null,
    selectionBeforeRanges: [],
    selectionAfterRanges: [],
    label: `${stroke.name || "インク"}の描画`,
  });
  renderSheet();
  updateSelectionUi();
  setStatus(`${stroke.name || "インク"}を描画しました。`);
}

function createInkStrokeFromPoints(points, tool = {}) {
  const sampled = simplifyInkPoints(points, 800).map((point) => ({
    x: roundCssNumber(point.x),
    y: roundCssNumber(point.y),
  }));
  if (sampled.length < 2) return null;
  return normalizeInkStrokes([{
    id: uniqueWorksheetObjectId("ink"),
    name: tool.label || "インク",
    tool: tool.type || "pen",
    color: tool.color || "#111827",
    width: tool.width || 2,
    opacity: tool.opacity ?? 1,
    points: sampled,
  }])[0] || null;
}

function inkStrokeColor(tool = {}) {
  const color = tool.color || "#111827";
  const opacity = Number(tool.opacity);
  if (!Number.isFinite(opacity) || opacity >= 0.999 || !/^#[0-9a-f]{6}$/i.test(color)) return color;
  const r = Number.parseInt(color.slice(1, 3), 16);
  const g = Number.parseInt(color.slice(3, 5), 16);
  const b = Number.parseInt(color.slice(5, 7), 16);
  return `rgba(${r},${g},${b},${Math.max(0.05, Math.min(1, opacity))})`;
}

function pointListBoundingBox(points, padding = 4) {
  const xs = points.map((point) => point.x);
  const ys = points.map((point) => point.y);
  const left = Math.max(rowHeaderWidthForSheet(activeSheet()), Math.min(...xs) - padding);
  const top = Math.max(COLUMN_HEADER_HEIGHT, Math.min(...ys) - padding);
  const right = Math.max(...xs) + padding;
  const bottom = Math.max(...ys) + padding;
  return {
    left,
    top,
    width: Math.max(12, right - left),
    height: Math.max(12, bottom - top),
  };
}

function inkStrokeBoundingBox(stroke, extraPadding = 0) {
  const points = Array.isArray(stroke?.points) ? stroke.points : [];
  if (!points.length) return { left: 0, top: 0, width: 0, height: 0 };
  const padding = Math.max(2, Number(stroke.width) || 2) / 2 + Math.max(0, Number(extraPadding) || 0);
  const xs = points.map((point) => Number(point.x)).filter(Number.isFinite);
  const ys = points.map((point) => Number(point.y)).filter(Number.isFinite);
  if (!xs.length || !ys.length) return { left: 0, top: 0, width: 0, height: 0 };
  const left = Math.min(...xs) - padding;
  const top = Math.min(...ys) - padding;
  const right = Math.max(...xs) + padding;
  const bottom = Math.max(...ys) + padding;
  return {
    left,
    top,
    width: Math.max(1, right - left),
    height: Math.max(1, bottom - top),
  };
}

function customPathFromSheetPoints(points, box) {
  const sampled = simplifyInkPoints(points, 120);
  const commands = sampled.map((point, index) => ({
    cmd: index === 0 ? "M" : "L",
    points: [{
      x: clamp01((point.x - box.left) / Math.max(1, box.width)),
      y: clamp01((point.y - box.top) / Math.max(1, box.height)),
    }],
  }));
  return normalizeShapeCustomPath({ commands });
}

function simplifyInkPoints(points, maxPoints) {
  if (points.length <= maxPoints) return points;
  const step = Math.ceil(points.length / maxPoints);
  const sampled = points.filter((_point, index) => index % step === 0);
  if (sampled.at(-1) !== points.at(-1)) sampled.push(points.at(-1));
  return sampled;
}

function svgPathDFromSheetPoints(points) {
  if (!points.length) return "";
  return points.map((point, index) => `${index === 0 ? "M" : "L"}${roundSvgNumber(point.x)} ${roundSvgNumber(point.y)}`).join(" ");
}

function eraseInkAtClientPoint(clientX, clientY, options = {}) {
  const point = sheetPixelFromClientPosition(clientX, clientY, { clampToGrid: true });
  if (!point) return;
  const sheet = activeSheet();
  const eraserTool = state.inkDrawing?.tool?.type === "eraser" ? state.inkDrawing.tool : state.pendingInkTool;
  const preset = DRAW_INK_ERASERS[eraserTool?.eraserKey] || DRAW_INK_ERASERS[state.currentInkEraser] || DRAW_INK_ERASERS.stroke;
  const mode = eraserTool?.eraserMode || preset.mode || "stroke";
  const radius = Math.max(2, Number(eraserTool?.eraserRadius ?? preset.radius) || preset.radius || 8);
  const eraseResult = mode === "point"
    ? eraseInkPointAtSheetPoint(sheet, point, radius)
    : eraseInkStrokeAtSheetPoint(sheet, point, radius);
  if (!eraseResult.changed) return;
  const before = state.inkDrawing?.tool?.type === "eraser" || options.deferHistory
    ? null
    : eraseResult.before;
  setSelectedImageIds([], null);
  if (state.inkDrawing?.tool?.type === "eraser" || options.deferHistory) {
    if (state.inkDrawing) state.inkDrawing.eraserChanged = true;
  } else {
    pushHistory({
      sheetIndex: state.activeSheetIndex,
      sheetBefore: before,
      sheetAfter: captureSheetForHistory(sheet),
      selectionBefore: activeSelectionRange(),
      selectionAfter: null,
      selectionBeforeRanges: activeSelectionRanges(),
      selectionAfterRanges: [],
      label: "インクの削除",
    });
  }
  renderSheet();
  setStatus("インクを削除しました。");
}

function eraseInkStrokeAtSheetPoint(sheet, point, radius = 8) {
  const targetStroke = hitTestInkStroke(sheet, point, Math.max(4, radius));
  const targetLegacyImage = targetStroke ? null : [...(sheet.images || [])].reverse().find((image) => image?.shape?.ink && pixelPointInsideImage(sheet, image, point, radius));
  if (!targetStroke && !targetLegacyImage) return { changed: false, before: null };
  const before = captureSheetForHistory(sheet);
  if (targetStroke) {
    sheet.inkStrokes = normalizeInkStrokes(sheet.inkStrokes).filter((stroke) => stroke.id !== targetStroke.id);
    state.selectedInkStrokeIds = (state.selectedInkStrokeIds || []).filter((id) => id !== targetStroke.id);
  } else {
    sheet.images = sheet.images.filter((image) => image.id !== targetLegacyImage.id);
  }
  return { changed: true, before };
}

function eraseInkPointAtSheetPoint(sheet, point, radius = 10) {
  const strokes = normalizeInkStrokes(sheet.inkStrokes);
  const nextStrokes = [];
  let changed = false;
  const changedIds = new Set();
  strokes.forEach((stroke) => {
    const effectiveRadius = Math.max(2, radius + Math.max(0.5, Number(stroke.width) || 2) / 2);
    const pointBox = { left: point.x - effectiveRadius, top: point.y - effectiveRadius, width: effectiveRadius * 2, height: effectiveRadius * 2 };
    if (!pixelBoxesIntersect(inkStrokeBoundingBox(stroke, effectiveRadius), pointBox)) {
      nextStrokes.push(stroke);
      return;
    }
    const result = eraseInkStrokePartAtPoint(stroke, point, effectiveRadius);
    if (!result.changed) {
      nextStrokes.push(stroke);
      return;
    }
    changed = true;
    changedIds.add(stroke.id);
    nextStrokes.push(...result.strokes);
  });
  const targetLegacyImage = changed ? null : [...(sheet.images || [])].reverse().find((image) => image?.shape?.ink && pixelPointInsideImage(sheet, image, point, radius));
  if (!changed && !targetLegacyImage) return { changed: false, before: null };
  const before = captureSheetForHistory(sheet);
  if (changed) {
    sheet.inkStrokes = normalizeInkStrokes(nextStrokes);
    const remainingIds = new Set(sheet.inkStrokes.map((stroke) => stroke.id));
    state.selectedInkStrokeIds = (state.selectedInkStrokeIds || []).filter((id) => remainingIds.has(id) && !changedIds.has(id));
  }
  if (targetLegacyImage) {
    sheet.images = sheet.images.filter((image) => image.id !== targetLegacyImage.id);
  }
  return { changed: true, before };
}

function eraseInkStrokePartAtPoint(stroke, center, radius) {
  const points = (stroke?.points || [])
    .map((point) => ({ x: Number(point.x), y: Number(point.y) }))
    .filter((point) => Number.isFinite(point.x) && Number.isFinite(point.y));
  if (points.length < 2) return { changed: false, strokes: [stroke] };
  const runs = [];
  let currentRun = [];
  let touched = false;
  const finishRun = () => {
    if (currentRun.length >= 2) runs.push(currentRun);
    currentRun = [];
  };
  const pushRunPoint = (point) => {
    const rounded = { x: roundCssNumber(point.x), y: roundCssNumber(point.y) };
    const last = currentRun.at(-1);
    if (!last || Math.hypot(last.x - rounded.x, last.y - rounded.y) > 0.35) currentRun.push(rounded);
  };
  for (let index = 1; index < points.length; index += 1) {
    const start = points[index - 1];
    const end = points[index];
    const startInside = Math.hypot(start.x - center.x, start.y - center.y) <= radius;
    const endInside = Math.hypot(end.x - center.x, end.y - center.y) <= radius;
    const segmentTouched = startInside || endInside || distancePointToSegment(center, start, end) <= radius;
    if (!segmentTouched) {
      if (!currentRun.length) pushRunPoint(start);
      pushRunPoint(end);
      continue;
    }
    touched = true;
    const intersections = segmentCircleIntersections(start, end, center, radius);
    if (!startInside && !currentRun.length) pushRunPoint(start);
    if (!startInside && endInside) {
      const entry = intersections[0];
      if (Number.isFinite(entry)) pushRunPoint(interpolateInkPoint(start, end, entry));
      finishRun();
      continue;
    }
    if (startInside && endInside) {
      finishRun();
      continue;
    }
    if (startInside && !endInside) {
      finishRun();
      const exit = intersections.at(-1);
      if (Number.isFinite(exit)) pushRunPoint(interpolateInkPoint(start, end, exit));
      pushRunPoint(end);
      continue;
    }
    if (intersections.length >= 2) {
      pushRunPoint(interpolateInkPoint(start, end, intersections[0]));
      finishRun();
      pushRunPoint(interpolateInkPoint(start, end, intersections[1]));
      pushRunPoint(end);
      continue;
    }
    pushRunPoint(end);
  }
  finishRun();
  if (!touched) return { changed: false, strokes: [stroke] };
  const strokes = runs.map((points, index) => normalizeInkStrokes([{
    ...stroke,
    id: index === 0 ? stroke.id : uniqueWorksheetObjectId("ink"),
    points,
  }])[0]).filter(Boolean);
  return { changed: true, strokes };
}

function segmentCircleIntersections(start, end, center, radius) {
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const a = dx * dx + dy * dy;
  if (a <= 0) return [];
  const fx = start.x - center.x;
  const fy = start.y - center.y;
  const b = 2 * (fx * dx + fy * dy);
  const c = fx * fx + fy * fy - radius * radius;
  const discriminant = b * b - 4 * a * c;
  if (discriminant < 0) return [];
  const root = Math.sqrt(Math.max(0, discriminant));
  const values = [(-b - root) / (2 * a), (-b + root) / (2 * a)]
    .filter((value) => value > 0 && value < 1)
    .sort((left, right) => left - right);
  return values.filter((value, index) => index === 0 || Math.abs(value - values[index - 1]) > 0.001);
}

function interpolateInkPoint(start, end, t) {
  return {
    x: start.x + (end.x - start.x) * t,
    y: start.y + (end.y - start.y) * t,
  };
}

function hitTestInkStroke(sheet, point, tolerance = 6) {
  const strokes = normalizeInkStrokes(sheet?.inkStrokes);
  for (let index = strokes.length - 1; index >= 0; index -= 1) {
    const stroke = strokes[index];
    const box = inkStrokeBoundingBox(stroke, tolerance);
    if (!pixelBoxesIntersect(box, { left: point.x, top: point.y, width: 1, height: 1 })) continue;
    const threshold = Math.max(tolerance, (Number(stroke.width) || 2) / 2 + tolerance);
    if (inkStrokeDistanceToPoint(stroke, point) <= threshold) return stroke;
  }
  return null;
}

function inkStrokeDistanceToPoint(stroke, point) {
  const points = stroke?.points || [];
  if (!points.length) return Number.POSITIVE_INFINITY;
  let best = Number.POSITIVE_INFINITY;
  for (let index = 1; index < points.length; index += 1) {
    best = Math.min(best, distancePointToSegment(point, points[index - 1], points[index]));
  }
  return best;
}

function distancePointToSegment(point, start, end) {
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const lengthSq = dx * dx + dy * dy;
  if (!lengthSq) return Math.hypot(point.x - start.x, point.y - start.y);
  const t = Math.max(0, Math.min(1, ((point.x - start.x) * dx + (point.y - start.y) * dy) / lengthSq));
  const x = start.x + dx * t;
  const y = start.y + dy * t;
  return Math.hypot(point.x - x, point.y - y);
}

function pixelPointInsideImage(sheet, image, point, padding = 0) {
  const box = imageVisualBoxToPixels(image, imageBoxToPixels(sheet, image));
  return Boolean(box && point.x >= box.left - padding && point.x <= box.left + box.width + padding && point.y >= box.top - padding && point.y <= box.top + box.height + padding);
}

function selectInkObjectsInsideLasso(points) {
  if (!points || points.length < 2) return;
  const sheet = activeSheet();
  const box = pointListBoundingBox(points, 0);
  const strokeIds = normalizeInkStrokes(sheet.inkStrokes)
    .filter((stroke) => {
      const strokeBox = inkStrokeBoundingBox(stroke);
      const center = { x: strokeBox.left + strokeBox.width / 2, y: strokeBox.top + strokeBox.height / 2 };
      return center.x >= box.left && center.x <= box.left + box.width && center.y >= box.top && center.y <= box.top + box.height;
    })
    .map((stroke) => stroke.id);
  const legacyIds = (sheet.images || [])
    .filter((image) => image?.shape?.ink)
    .filter((image) => {
      const imageBox = imageVisualBoxToPixels(image, imageBoxToPixels(sheet, image));
      if (!imageBox) return false;
      const center = { x: imageBox.left + imageBox.width / 2, y: imageBox.top + imageBox.height / 2 };
      return center.x >= box.left && center.x <= box.left + box.width && center.y >= box.top && center.y <= box.top + box.height;
    })
    .map((image) => image.id);
  if (!strokeIds.length && !legacyIds.length) {
    setStatus("なげなわ範囲にインクがありません。");
    return;
  }
  setSelectedImageIds(legacyIds, legacyIds[0]);
  state.selectedInkStrokeIds = strokeIds;
  renderSheet();
  updateSelectionUi();
  setStatus(`${strokeIds.length + legacyIds.length} 個のインクを選択しました。`);
}

function convertSelectedInkToFreeformShape() {
  const sheet = activeSheet();
  const selectedStrokeIds = selectedInkStrokeIdSet();
  const strokes = normalizeInkStrokes(sheet.inkStrokes).filter((stroke) => selectedStrokeIds.has(stroke.id));
  const legacyImages = selectedImageObjects().filter((image) => image?.shape?.ink);
  if (!strokes.length && !legacyImages.length) {
    setStatus("変換するインクを選択してください。");
    return;
  }
  if (!ensureSheetProtectionPermission(sheet, "allowEditObjects", "保護されたシートではインクを図形に変換できません。")) return;
  const before = captureSheetForHistory(sheet);
  const insertedIds = [];
  strokes.forEach((stroke) => {
    const box = inkStrokeBoundingBox(stroke, Math.max(2, stroke.width || 2));
    const customPath = customPathFromSheetPoints(stroke.points, box);
    if (!customPath) return;
    const descriptor = shapeDescriptorForType(CUSTOM_SHAPE_TYPE, {
      width: box.width,
      height: box.height,
      customPath,
      fillColor: "none",
      outlineColor: inkStrokeColor(stroke),
      outlineWidth: stroke.width || 2,
      lineCap: "round",
      lineJoin: "round",
    });
    descriptor.name = stroke.name?.replace(/^インク/, "自由図形") || "自由図形";
    descriptor.shape = {
      ...descriptor.shape,
      ink: false,
      label: "自由図形",
      fillColor: "none",
    };
    const image = addShapeAtPixelBoxToSheet(sheet, CUSTOM_SHAPE_TYPE, box, descriptor);
    if (!image) return;
    image.name = descriptor.name;
    image.src = descriptor.src;
    image.shape = descriptor.shape;
    refreshShapeSource(image);
    insertedIds.push(image.id);
  });
  sheet.inkStrokes = normalizeInkStrokes(sheet.inkStrokes).filter((stroke) => !selectedStrokeIds.has(stroke.id));
  legacyImages.forEach((image) => {
    image.name = image.name?.replace(/^インク/, "自由図形") || "自由図形";
    image.shape = { ...(image.shape || {}), ink: false, label: "自由図形", fillColor: "none" };
    refreshShapeSource(image);
    insertedIds.push(image.id);
  });
  state.selectedInkStrokeIds = [];
  setSelectedImageIds(insertedIds, insertedIds[0]);
  pushHistory({
    sheetIndex: state.activeSheetIndex,
    sheetBefore: before,
    sheetAfter: captureSheetForHistory(sheet),
    selectionBefore: activeSelectionRange(),
    selectionAfter: null,
    selectionBeforeRanges: activeSelectionRanges(),
    selectionAfterRanges: [],
    label: "インクを図形に変換",
  });
  renderSheet();
  updateSelectionUi();
  setStatus(`${strokes.length + legacyImages.length} 個のインクを図形に変換しました。`);
}

function clearInkObjects() {
  const sheet = activeSheet();
  const strokes = normalizeInkStrokes(sheet.inkStrokes);
  const targets = (sheet.images || []).filter((image) => image?.shape?.ink);
  if (!strokes.length && !targets.length) {
    setStatus("削除するインクがありません。");
    return;
  }
  const before = captureSheetForHistory(sheet);
  const ids = new Set(targets.map((image) => image.id));
  sheet.inkStrokes = [];
  sheet.images = sheet.images.filter((image) => !ids.has(image.id));
  state.selectedInkStrokeIds = [];
  setSelectedImageIds([], null);
  pushHistory({
    sheetIndex: state.activeSheetIndex,
    sheetBefore: before,
    sheetAfter: captureSheetForHistory(sheet),
    selectionBefore: activeSelectionRange(),
    selectionAfter: activeSelectionRange(),
    selectionBeforeRanges: activeSelectionRanges(),
    selectionAfterRanges: activeSelectionRanges(),
    label: "インクの削除",
  });
  renderSheet();
  setStatus(`${strokes.length + targets.length} 個のインクを削除しました。`);
}

function autoSumOperationsForRanges(sheet, sheetId, ranges, functionName = "SUM", sheetIndex = state.activeSheetIndex) {
  const operations = [];
  const formulaName = normalizeAutoSumFunctionName(functionName);
  (ranges.length ? ranges : [activeSelectionRange()]).filter(Boolean).forEach((range) => {
    if (isSingleCellRange(range)) {
      const formula = autoSumFormulaForCell(sheet, sheetId, range.top, range.left, formulaName, sheetIndex);
      if (formula) operations.push({ target: normalizeRange({ sheetIndex, row: range.top, col: range.left }, { sheetIndex, row: range.top, col: range.left }), formula });
      return;
    }

    const width = range.right - range.left + 1;
    const height = range.bottom - range.top + 1;
    if (height >= width) {
      const bottomBlank = rangeBottomRowIsBlank(sheet, range);
      const targetRow = bottomBlank ? range.bottom : range.bottom + 1;
      const sourceTop = range.top;
      const sourceBottom = bottomBlank ? range.bottom - 1 : range.bottom;
      for (let col = range.left; col <= range.right; col += 1) {
        if (sourceBottom < sourceTop) continue;
        const source = normalizeRange({ sheetIndex, row: sourceTop, col }, { sheetIndex, row: sourceBottom, col });
        if (!rangeHasSummableCell(sheet, sheetId, source)) continue;
        operations.push({
          target: normalizeRange({ sheetIndex, row: targetRow, col }, { sheetIndex, row: targetRow, col }),
          formula: `=${formulaName}(${rangeToLabel(source)})`,
        });
      }
      return;
    }

    const rightBlank = rangeRightColumnIsBlank(sheet, range);
    const targetCol = rightBlank ? range.right : range.right + 1;
    const sourceLeft = range.left;
    const sourceRight = rightBlank ? range.right - 1 : range.right;
    for (let row = range.top; row <= range.bottom; row += 1) {
      if (sourceRight < sourceLeft) continue;
      const source = normalizeRange({ sheetIndex, row, col: sourceLeft }, { sheetIndex, row, col: sourceRight });
      if (!rangeHasSummableCell(sheet, sheetId, source)) continue;
      operations.push({
        target: normalizeRange({ sheetIndex, row, col: targetCol }, { sheetIndex, row, col: targetCol }),
        formula: `=${formulaName}(${rangeToLabel(source)})`,
      });
    }
  });
  return operations;
}

function autoSumFormulaForCell(sheet, sheetId, row, col, functionName = "SUM", sheetIndex = state.activeSheetIndex) {
  const formulaName = normalizeAutoSumFunctionName(functionName);
  const vertical = contiguousAutoSumSource(sheet, sheetId, row - 1, col, -1, 0, sheetIndex);
  if (vertical) return `=${formulaName}(${rangeToLabel(vertical)})`;
  const horizontal = contiguousAutoSumSource(sheet, sheetId, row, col - 1, 0, -1, sheetIndex);
  if (horizontal) return `=${formulaName}(${rangeToLabel(horizontal)})`;
  return "";
}

function contiguousAutoSumSource(sheet, sheetId, startRow, startCol, rowStep, colStep, sheetIndex = state.activeSheetIndex) {
  let row = startRow;
  let col = startCol;
  let first = null;
  let last = null;
  while (row >= 1 && col >= 1 && autoSumCellLooksSummable(sheet, sheetId, row, col)) {
    const point = { sheetIndex, row, col };
    if (!first) first = point;
    last = point;
    row += rowStep;
    col += colStep;
  }
  if (!first || !last) return null;
  return normalizeRange(first, last);
}

function autoSumCellLooksSummable(sheet, sheetId, row, col) {
  const cell = sheet.cells[cellKey(row, col)];
  if (!cell) return false;
  if (cell.formula || (typeof cell.raw === "string" && cell.raw.startsWith("="))) return true;
  const value = cell.raw ?? cell.cached ?? getDisplayForCell(sheet, sheetId, row, col);
  if (value == null || String(value).trim() === "") return false;
  if (typeof value === "number") return Number.isFinite(value);
  return Number.isFinite(Number(String(value).replace(/,/g, "")));
}

function rangeHasSummableCell(sheet, sheetId, range) {
  let found = false;
  forEachCellInRange(range, (row, col) => {
    if (!found && autoSumCellLooksSummable(sheet, sheetId, row, col)) found = true;
  });
  return found;
}

function rangeBottomRowIsBlank(sheet, range) {
  for (let col = range.left; col <= range.right; col += 1) {
    if (cellHasDataForRegion(sheet, range.bottom, col)) return false;
  }
  return true;
}

function rangeRightColumnIsBlank(sheet, range) {
  for (let row = range.top; row <= range.bottom; row += 1) {
    if (cellHasDataForRegion(sheet, row, range.right)) return false;
  }
  return true;
}

